'use strict';
const childProcess = require('child_process');
const { mergePromise, getSpawnedPromise } = require('./lib/promise');
const { spawnedKill, spawnedCancel, setupTimeout, setExitHandler } = require('./lib/kill');

// The flow of execa's index.js: patch kill/cancel onto the child, build the
// deferred result promise, and mix then/catch/finally into the child.
function start(code, options = {}) {
  const spawned = childProcess.spawn('node', ['-e', code]);
  const context = { isCanceled: false };
  spawned.kill = spawnedKill.bind(null, spawned.kill.bind(spawned));
  spawned.cancel = spawnedCancel.bind(null, spawned, context);
  let stdout = '';
  let markEnded;
  const ended = new Promise((resolve) => {
    markEnded = resolve;
  });
  if (spawned.stdout) {
    spawned.stdout.on('data', (chunk) => {
      stdout += chunk;
    });
    spawned.stdout.on('end', () => markEnded());
  }
  const spawnedPromise = getSpawnedPromise(spawned);
  const timedPromise = setupTimeout(spawned, options, spawnedPromise);
  const processDone = setExitHandler(spawned, { cleanup: true }, timedPromise);
  let started;
  const handlePromiseOnce = () => {
    if (!started) {
      started = (async () => {
        const { exitCode, signal } = await processDone;
        await ended;
        if (exitCode !== 0 || signal !== null) {
          const error = new Error(`Command failed: exit ${exitCode}, signal ${signal}`);
          error.exitCode = exitCode;
          error.isCanceled = context.isCanceled;
          throw error;
        }
        return { exitCode, stdout: stdout.trim() };
      })();
    }
    return started;
  };
  return mergePromise(spawned, handlePromiseOnce);
}

exports.run = async () => {
  const lines = [];
  const first = start('console.log("hello from child")');
  lines.push(`types: ${typeof first.then} ${typeof first.catch} ${typeof first.finally} ${typeof first.kill} ${typeof first.pid}`);
  const d = Reflect.getOwnPropertyDescriptor(first, 'then');
  lines.push(`then descriptor: writable=${d.writable} enumerable=${d.enumerable} configurable=${d.configurable}`);
  const result = await first;
  lines.push(`awaited: ${result.exitCode} ${result.stdout}`);

  const code = await start('console.log(41 + 1)').then((r) => r.stdout);
  lines.push(`then: ${code}`);

  const failed = await start('process.exitCode = 3').catch((e) => `caught ${e.exitCode} ${e.isCanceled}`);
  lines.push(failed);

  let finalized = false;
  const value = await start('console.log("done")').finally(() => {
    finalized = true;
  });
  lines.push(`finally: ${value.stdout} ${finalized}`);

  const slow = start('setTimeout(() => {}, 10000)');
  slow.cancel();
  try {
    await slow;
  } catch (e) {
    lines.push(`canceled: ${e.isCanceled} ${e.message}`);
  }

  const killed = start('setTimeout(() => {}, 10000)');
  lines.push(`kill: ${killed.kill('SIGTERM', { forceKillAfterTimeout: false })}`);
  try {
    await killed;
  } catch (e) {
    lines.push(`killed: ${e.isCanceled} ${e.message}`);
  }

  try {
    await start('setTimeout(() => {}, 10000)', { timeout: 50 });
  } catch (e) {
    lines.push(`timeout: ${e.timedOut} ${e.signal} ${e.message}`);
  }
  return lines;
};
